#pragma once

// What a Klipper printer's multi-filament unit reports as loaded, read from
// its Moonraker host, and how fresh that reading is. No wx and no Orca types:
// the parsing and the freshness rules are testable without a GUI or a
// printer. HostLaneReader does the network half and hands readings in here.
//
// The two sources and what they mean mirror OrcaSlicer's own
// MoonrakerPrinterAgent (fetch_moonraker_filament_data and
// fetch_hh_filament_info). That agent cannot be called for this: its readers
// are private, run on the calling thread, and write the shared device state;
// and its status stream is compiled out, so the device it feeds never counts
// as live. When upstream changes what those two functions accept, change the
// parsers here to match.

#include <chrono>
#include <map>
#include <mutex>
#include <optional>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::Printers {

// One lane that holds filament. `colour` is "#RRGGBB", or empty when the lane
// reported none or one that is not a colour: a missing colour is not white.
struct HostLane
{
    int         index{0}; // the lane's tool number, from 0
    std::string material; // as the unit names it, such as "PLA"
    std::string colour;
};

// A reply read as one of the two sources. `unit` is false when the source
// shows no multi-filament unit; `loaded` then is empty.
struct UnitReport
{
    bool                  unit{false};
    std::vector<HostLane> loaded; // in lane order
};

// "#RRGGBB" for "#RRGGBB", "RRGGBB", "0xRRGGBB" or "RRGGBBAA"; empty otherwise.
std::string lane_colour(const std::string& raw);

// The body of GET /server/database/item?namespace=lane_data (AFC, and Happy
// Hare since February 2026). A unit is there when any entry has a lane
// number; a lane holds filament when it names a material. Nothing when the
// body is not that reply.
std::optional<UnitReport> parse_lane_data(const std::string& body);

// The body of GET /printer/objects/query?mmu (Happy Hare). A unit is there
// when `mmu` names a positive gate count; a gate holds filament when its
// status is above zero and it names a material. Nothing when the body is not
// that reply.
std::optional<UnitReport> parse_happy_hare(const std::string& body);

// What one attempt to read a host found.
struct HostReading
{
    // The host answered: as Moonraker does, for a Moonraker host; with any
    // HTTP reply at its page, for any other.
    bool reached{false};
    // What is loaded, when the host said: empty for a unit with nothing loaded
    // and for a printer with no unit alike -- both are the printer saying
    // there is nothing to show. Absent when the host did not say.
    std::optional<std::vector<HostLane>> loaded;
};

enum class HostLink { Checking, Reachable, Unreachable };

struct HostStatus
{
    HostLink                             link{HostLink::Checking};
    // Only while Reachable, and only when the host said.
    std::optional<std::vector<HostLane>> loaded;
};

// A reading counts for as long as a Bambu printer's pushed data does
// (PrinterSetup::has_recent_printer_data): three missed polls.
inline constexpr std::chrono::seconds kHostReadingFresh{30};
inline constexpr std::chrono::seconds kHostPollInterval{10};

// The latest reading of each host, keyed by whatever identifies the host's
// settings: a changed address or key is a different host. Thread-safe: the
// readings arrive on worker threads.
class HostReadings
{
public:
    using Clock = std::chrono::steady_clock;

    // Reachable while an answer is fresh; Unreachable while the last attempt,
    // itself fresh, failed with no fresh answer; Checking otherwise -- never
    // asked, or asked too long ago to say.
    HostStatus status(const std::string& key, Clock::time_point now) const;

    // True, and the attempt recorded as started, when `key` is due another
    // read: none in flight and none started in the last poll interval.
    bool begin(const std::string& key, Clock::time_point now);
    void finish(const std::string& key, HostReading reading, Clock::time_point now);

    // The host answered some other request, such as a connection test. It
    // says nothing about what is loaded.
    void note_answered(const std::string& key, Clock::time_point now);

private:
    struct Entry
    {
        std::optional<Clock::time_point>     started;
        bool                                 in_flight{false};
        std::optional<Clock::time_point>     answered;  // last time the host answered
        std::optional<Clock::time_point>     failed;    // last attempt that got no answer
        std::optional<std::vector<HostLane>> loaded;    // from the last answer
    };

    mutable std::mutex           m_mutex;
    std::map<std::string, Entry> m_entries;
};

} // namespace Slic3r::GUI::JusPrin::Printers
#pragma once

// Reads whether a named printer's print host answers, and what a Moonraker
// host says its multi-filament unit holds, off the UI thread, and keeps the
// latest reading for Home's printer cards, the header's printer menu and the
// printer conversation. Only printers connected to a print host are read; the
// printer agent Orca has selected is not involved, so a Bambu printer's live
// connection is left as it is.
//
// Nothing here blocks: a caller gets the reading as it stands and, when one
// is due, starts the next. Readings are asked for only while something shows
// them, so a host is not polled while Home is off screen.

#include "HostLanes.hpp"

#include <optional>
#include <string>

namespace Slic3r::GUI::JusPrin::Printers {

// The latest reading of the named printer `name`, starting another when one
// is due. Nothing when that printer has no print host.
std::optional<HostStatus> host_status(const std::string& name);

// Starts every due read, for all named printers with a print host.
void refresh_host_readings();

// The named printer's host has just answered a connection test.
void note_host_answered(const std::string& name);

} // namespace Slic3r::GUI::JusPrin::Printers
#include "HostLaneReader.hpp"

#include "NamedPrinters.hpp"
#include "libslic3r/PresetBundle.hpp"
#include "libslic3r/PrintConfig.hpp"
#include "slic3r/GUI/GUI_App.hpp"
#include "slic3r/Utils/Http.hpp"
#include "slic3r/Utils/Moonraker.hpp"
#include "slic3r/Utils/PrintHost.hpp"

#include <atomic>
#include <chrono>
#include <functional>
#include <memory>
#include <thread>
#include <utility>

namespace Slic3r::GUI::JusPrin::Printers {

namespace {

// The reads in flight. A read runs on a thread nothing joins, and Http's curl
// is torn down with the process's statics; a read still inside curl then
// would crash the exit. So the app's exit stops new reads and cancels those
// in flight, and waits a moment for them to leave.
struct Reads
{
    std::atomic<bool> stopping{false};
    std::atomic<int>  running{0};
};

const std::shared_ptr<Reads>& reads()
{
    static const auto shared = std::make_shared<Reads>();
    return shared;
}

struct StopReadsAtExit
{
    // Its own reference: the static behind reads() may be gone first.
    std::shared_ptr<Reads> m_reads = reads();

    ~StopReadsAtExit()
    {
        m_reads->stopping = true;
        // Curl checks for cancellation about once a second while it waits.
        const auto until = std::chrono::steady_clock::now() + std::chrono::seconds(3);
        while (m_reads->running > 0 && std::chrono::steady_clock::now() < until)
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }
};

// Orca's Moonraker print host, for its address and credential handling only:
// the same URL, API key, CA file and revocation setting an upload uses.
class LaneReader final : public Moonraker
{
public:
    // Moonraker copies what it reads from the config, so the copy passed in
    // need not outlive the constructor.
    LaneReader(DynamicPrintConfig config, std::shared_ptr<Reads> reads) : Moonraker(&config), m_reads(std::move(reads)) {}

    HostReading read() const
    {
        HostReading reading;
        const auto [status, body] = get("server/database/item?namespace=lane_data");
        // Moonraker answers 404 for a namespace nothing has written: a printer
        // without such a unit, which still answered.
        if (status != 200 && status != 404)
            return reading;
        reading.reached = true;
        if (status == 200)
            if (const auto report = parse_lane_data(body); report && report->unit) {
                reading.loaded = report->loaded;
                return reading;
            }
        const auto [mmu_status, mmu_body] = get("printer/objects/query?mmu");
        // Klippy not ready answers 503, and says nothing either way.
        if (mmu_status == 200)
            if (const auto report = parse_happy_hare(mmu_body))
                reading.loaded = report->unit ? report->loaded : std::vector<HostLane>();
        return reading;
    }

private:
    // The HTTP status, zero when nothing answered, and the body.
    std::pair<unsigned, std::string> get(const std::string& path) const
    {
        unsigned    status = 0;
        std::string body;
        auto        http = Http::get(make_url(path));
        set_auth(http);
        http.timeout_connect(5)
            .timeout_max(10)
            .on_complete([&](std::string reply, unsigned code) {
                status = code;
                body   = std::move(reply);
            })
            .on_error([&](std::string reply, std::string, unsigned code) {
                status = code;
                body   = std::move(reply);
            })
            .on_progress([this](Http::Progress, bool& cancel) { cancel = m_reads->stopping; })
#ifdef WIN32
            .ssl_revoke_best_effort(m_ssl_revoke_best_effort)
#endif
            .perform_sync();
        return {status, body};
    }

    std::shared_ptr<Reads> m_reads;
};

// Any other print host -- OctoPrint, PrusaLink and the like -- is asked only
// whether it answers at the page its printer window loads: any HTTP reply
// counts, a login page or a refused key included, since the page is there.
// What is loaded is not asked; each host says it differently, if at all.
HostReading probe_page(const DynamicPrintConfig& config, const std::shared_ptr<Reads>& in_flight)
{
    // Http reports an HTTP error with its status and a failure to get any
    // reply with status zero; a reply it reports neither way (a final 3xx)
    // is still a reply.
    bool answered = true;
    // get_print_host_webui takes a mutable config; it only reads it.
    DynamicPrintConfig copy = config;
    Http::get(PrintHost::get_print_host_webui(&copy))
        .timeout_connect(5)
        .timeout_max(10)
        .on_error([&](std::string, std::string, unsigned code) { answered = code != 0; })
        .on_progress([&](Http::Progress, bool& cancel) { cancel = in_flight->stopping; })
        .perform_sync();
    HostReading reading;
    reading.reached = answered;
    return reading;
}

// Shared with the reads in flight, which may finish after the app has
// started to exit.
const std::shared_ptr<HostReadings>& readings()
{
    static const auto shared = std::make_shared<HostReadings>();
    return shared;
}

// The named printer's saved profile, when it is connected to a print host.
const Preset* host_printer(const std::string& name)
{
    PresetBundle* bundle = wxGetApp().preset_bundle;
    if (bundle == nullptr)
        return nullptr;
    const Preset* preset = bundle->printers.find_preset(name, false, true);
    if (preset == nullptr || !is_named_printer(*preset))
        return nullptr;
    if (preset->config.opt_string("print_host").empty())
        return nullptr;
    return preset;
}

bool is_moonraker(const DynamicPrintConfig& config)
{
    const auto* type = config.option<ConfigOptionEnum<PrintHostType>>("host_type");
    return type != nullptr && type->value == htMoonraker;
}

// A reading belongs to the settings it was taken with: a printer given
// another address or key starts again from nothing.
std::string host_key(const std::string& name, const DynamicPrintConfig& config)
{
    std::string key = name;
    for (const char* option : {"print_host", "printhost_apikey", "printhost_cafile"})
        key += '\n' + config.opt_string(option);
    return key;
}

} // namespace

std::optional<HostStatus> host_status(const std::string& name)
{
    const Preset* preset = host_printer(name);
    if (preset == nullptr)
        return std::nullopt;
    const std::string key = host_key(name, preset->config);
    const auto        now = HostReadings::Clock::now();
    // Constructed after Http's curl state, so destroyed before it.
    static StopReadsAtExit stop_at_exit;
    if (!reads()->stopping && readings()->begin(key, now)) {
        ++reads()->running;
        std::function<HostReading()> read;
        if (is_moonraker(preset->config)) {
            auto reader = std::make_shared<const LaneReader>(preset->config, reads());
            read        = [reader] { return reader->read(); };
        } else {
            read = [config = preset->config, in_flight = reads()] { return probe_page(config, in_flight); };
        }
        std::thread([shared = readings(), in_flight = reads(), key, read = std::move(read)] {
            shared->finish(key, read(), HostReadings::Clock::now());
            --in_flight->running;
        }).detach();
    }
    return readings()->status(key, now);
}

void refresh_host_readings()
{
    for (const NamedPrinter& printer : named_printers())
        host_status(printer.name);
}

void note_host_answered(const std::string& name)
{
    if (const Preset* preset = host_printer(name))
        readings()->note_answered(host_key(name, preset->config), HostReadings::Clock::now());
}

} // namespace Slic3r::GUI::JusPrin::Printers

#pragma once

// The data behind the Home page, and the one function that turns it into the
// `state` payload of the jusprin-home-bridge protocol. No wx and no Orca types
// appear here, so the payload's shape is testable without a GUI: everything
// that needs a MainFrame, a PresetBundle, or the device layer lives in
// HomeHost, which fills these structs and hands them over.
//
// Optional fields are omitted from the JSON rather than sent as null or as an
// empty string: the page distinguishes "the host has nothing to say" from "the
// host says it is empty", and a serialised null would read as the latter.

#include <nlohmann/json_fwd.hpp>

#include <cstddef>
#include <string>
#include <vector>

namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {

// Matches ProjectStatusKind in the page's protocol.ts. 'unknown' is a project
// whose records could not be read, and has no line; only 'printing' earns a
// colored dot on the card.
enum class ProjectStatusKind { Unknown, Draft, Sent, Printing, Completed };

const char* to_string(ProjectStatusKind kind);

// What a card or the project pane says about a print history: how much went
// out, how much printed, and how it stands. The page phrases it.
struct HistorySummary
{
    std::size_t gcodes{0};
    std::size_t exports{0};
    std::size_t sends{0};
    std::size_t prints{0};
    std::size_t printing_now{0};
    // The newest finish, ISO 8601 in UTC; empty when nothing finished.
    std::string last_finished_at;

    bool empty() const { return gcodes == 0; }
};

// { gcodes, exports, sends, prints, printingNow, lastFinishedAt? }
nlohmann::json summary_json(const HistorySummary& summary);

struct ProjectEntry
{
    std::string        id;
    std::string        name;
    std::string        path;
    std::string        thumbnail_url; // empty when no preview is available
    // When the model was last saved, ISO 8601 in UTC; the page says it as
    // "Today", "Yesterday" or a date.
    std::string        updated_at;
    ProjectStatusKind  status_kind{ProjectStatusKind::Unknown};
    std::string        status_text;
    // The card's print-history line; an empty one draws none.
    HistorySummary     history;
};

// A spool the printer holds, as a connected printer reports its tray. Either
// field may be empty: a tray that reports no colour is still a material the
// card can name.
struct SpoolEntry
{
    std::string material; // the filament type, such as "PLA"
    std::string colour;   // '#RRGGBB'
};

enum class PrinterState { Idle, Printing, Offline };

const char* to_string(PrinterState state);

// What a card stands for, which decides how the page asks about its actions.
// A named printer is one the person added and names in JusPrin; the page
// confirms a rename or removal itself. A device is a Bambu printer on the
// network or the account that no named printer stands for; its rename and
// removal are Orca's own dialogs, which confirm for themselves.
enum class PrinterKind { Named, Device };

const char* to_string(PrinterKind kind);

// What a card's connection line and dot rest on, apart from its words.
// Online and Offline are a Bambu device's: data in the last 30 seconds, or
// verified before and silent now. Connected is a print host's: an address is
// saved, and for a Moonraker host, it answered in the last 30 seconds; a
// Moonraker host that stopped answering is Offline too. None is neither, and
// draws no dot.
enum class ConnectionState { None, Online, Offline, Connected };

