// The reply's `result` object, or nothing.
std::optional<json> result_of(const std::string& body)
{
    auto reply = parse(body);
    if (!reply)
        return std::nullopt;
    const auto result = reply->find("result");
    if (result == reply->end() || !result->is_object())
        return std::nullopt;
