bool FakeBambuAgent::apply_control_json(const std::string& json_text, FakeBambuStatusStep& step, bool& offline)
{
    json j = json::parse(json_text, nullptr, false);
    if (j.is_discarded() || !j.is_object())
        return false;

    if (j.contains("offline") && j["offline"].is_boolean())
        offline = j["offline"].get<bool>();

    std::string state = "idle";
    if (j.contains("state") && j["state"].is_string())
        state = lower_ascii(j["state"].get<std::string>());

    if (state == "idle")
        step.gcode_state = "IDLE";
    else if (state == "heating" || state == "prepare")
        step.gcode_state = "PREPARE";
    else if (state == "printing" || state == "running")
        step.gcode_state = "RUNNING";
    else if (state == "pause" || state == "paused")
        step.gcode_state = "PAUSE";
    else if (state == "finished" || state == "finish")
        step.gcode_state = "FINISH";
    else if (state == "failed" || state == "error")
        step.gcode_state = "FAILED";
    else
        return false;

    if (j.contains("progress") && j["progress"].is_number()) {
        const double progress = j["progress"].get<double>();
        step.mc_percent       = std::clamp(static_cast<int>(progress * 100.0 + 0.5), 0, 100);
    } else if (step.gcode_state == "FINISH") {
        step.mc_percent = 100;
    } else if (step.gcode_state == "IDLE" || step.gcode_state == "PREPARE") {
        step.mc_percent = 0;
    }

    step.mc_remaining_time = (step.gcode_state == "RUNNING" || step.gcode_state == "PAUSE") ?

};

struct FakeBambuStatusStep
{
    int         delay_ms             = 0;
    std::string gcode_state          = "IDLE";
    int         mc_percent           = 0;
    int         mc_remaining_time    = 0;
    double      nozzle_temper        = 25.0;
    double      nozzle_target_temper = 0.0;
    double      bed_temper           = 25.0;
    double      bed_target_temper    = 0.0;
    // Empty means no AMS reported at all, matching every step before this
    // field existed -- the default scenario and presets stay AMS-free.
    std::vector<FakeBambuSpool> spools;
};

// In-process stand-in for BBLPrinterAgent. A real Bambu preset stays selected;
// switch_printer_agent substitutes this implementation when jusprin.fake_printer
// is set. Status is driven by <datadir>/jusprin/fake_printer.json.
class FakeBambuAgent : public IPrinterAgent
{
public:
    explicit FakeBambuAgent(std::string log_dir);
    ~FakeBambuAgent() override;

    static AgentInfo get_agent_info_static();
    AgentInfo        get_agent_info() override { return get_agent_info_static(); }

    static std::vector<FakeBambuStatusStep>                               build_default_print_scenario();
    static std::vector<std::pair<std::string, FakeBambuStatusStep>>       build_named_presets();
    step.mc_remaining_time = (step.gcode_state == "RUNNING" || step.gcode_state == "PAUSE") ?
                                 remaining_minutes_from_progress(step.mc_percent) :
                                 0;

    if (j.contains("nozzle") && j["nozzle"].is_number()) {
        step.nozzle_temper = j["nozzle"].get<double>();
        step.nozzle_target_temper = (step.gcode_state == "IDLE" || step.gcode_state == "FINISH" || step.gcode_state == "FAILED") ?
                                        0.0 :
                                        step.nozzle_temper;
    }
    if (j.contains("bed") && j["bed"].is_number()) {
        step.bed_temper = j["bed"].get<double>();
        step.bed_target_temper = (step.gcode_state == "IDLE" || step.gcode_state == "FINISH" || step.gcode_state == "FAILED") ?
                                     0.0 :
                                     step.bed_temper;
    }
    // Present and an array replaces the loaded spools wholesale, same as
    // every other field here; absent leaves whatever the step already had
    // rather than clearing it, so a later poll that only touches state or
    // progress does not silently drop what an earlier one loaded.
    if (j.contains("spools") && j["spools"].is_array()) {
        step.spools.clear();
        for (const json& entry : j["spools"]) {
            if (!entry.is_object())
                continue;
            FakeBambuSpool spool;
            if (entry.contains("subBrands") && entry["subBrands"].is_string())
                spool.sub_brands = entry["subBrands"].get<std::string>();
            if (entry.contains("trayType") && entry["trayType"].is_string())
                spool.tray_type = entry["trayType"].get<std::string>();
            if (entry.contains("colour") && entry["colour"].is_string())
                spool.colour = entry["colour"].get<std::string>();
            if (entry.contains("filamentId") && entry["filamentId"].is_string())
                spool.filament_id = entry["filamentId"].get<std::string>();
            step.spools.push_back(std::move(spool));
        }
    }
    return true;
}

